file.content:
   @font-face Declarations (self-hosted variable fonts)
   -------------------------------------------------------------------------- */

@font-face {
  font-family: "Inter";
  src: url("/fonts/Inter-Variable.woff2") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Inter";
  src: url("/fonts/Inter-Italic-Variable.woff2") format("woff2");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "Source Serif 4";
  src: url("/fonts/SourceSerif4-Variable.woff2") format("woff2");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Source Serif 4";
  src: url("/fonts/SourceSerif4-Italic-Variable.woff2") format("woff2");
  font-weight: 200 900;
  font-style: italic;
  font-display: swap;
}

/* --------------------------------------------------------------------------
   CSS Variables
   -------------------------------------------------------------------------- */

:root {
  /* Brand Colors (calm, institutional) */
  --color-burgundy: #570d0b;
  --color-burgundy-hover: #4a0b09;
  --color-burgundy-soft: #7a2420;

  /* Neutrals */
  --color-stone: #f5f0f0;
  --color-sand: #e8d8d6;
  --color-sand-dark: #d4c4c2;
  --color-white: #ffffff;
  --color-charcoal: #1a1a1a;
  --color-black: #0f0f0f;

  /* Grays */
  --color-gray-50: #fafafa;
  --color-gray-100: #f5f5f5;
  --color-gray-200: #e5e5e5;
  --color-gray-300: #d4d4d4;
  --color-gray-400: #a3a3a3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;

  /* System Family Accent */
  --color-greenblocks: #3b8f5a;

  /* Semantic Tokens */
  --color-primary: var(--color-burgundy);
  --color-primary-hover: var(--color-burgundy-hover);
  --color-background: var(--color-stone);
  --color-background-elevated: var(--color-white);
  --color-surface: var(--color-sand);
  --color-text: var(--color-charcoal);
  --color-text-muted: rgba(26, 26, 26, 0.78);
  --color-border: var(--color-sand-dark);
  --color-link: var(--color-burgundy);

  /* Typography */
  --font-heading:
    "Source Serif 4", ui-serif, Georgia, "Times New Roman", Times, serif;
  --font-body:
    "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;

