() => {
  const reveal = [...document.querySelectorAll('.gb-reveal')];
  const grid = document.querySelector('.gb-enables-grid');
  const sysBody = document.querySelector('.gb-system-body');
  return {
    revealVisibleCount: reveal.filter(e => e.classList.contains('visible')).length,
    revealTotal: reveal.length,
    enablesColumns: grid ? getComputedStyle(grid).gridTemplateColumns : 'n/a',
    systemBodyAlign: sysBody ? getComputedStyle(sysBody).textAlign : 'n/a',
  };
}

async () => {
  window.scrollTo(0, document.body.scrollHeight);
  await new Promise(r => setTimeout(r, 1200));
  const reveal = [...document.querySelectorAll('.gb-reveal')];
  return {
    revealVisibleCount: reveal.filter(e => e.classList.contains('visible')).length,
    revealTotal: reveal.length,
    lastSectionOpacity: getComputedStyle(reveal[reveal.length - 1]).opacity,
  };
}

