async () => {
  // scroll to enables section, let observer + stagger settle
  const enables = document.querySelector('#enables');
  enables.scrollIntoView();
  await new Promise(r => setTimeout(r, 1400));
  const cards = [...document.querySelectorAll('.gb-enables-card')];
  const tiles = [...document.querySelectorAll('.gb-problem-tile')];
  return {
    enablesCards: cards.map(c => ({
      delay: getComputedStyle(c).transitionDelay,
      transform: getComputedStyle(c).transform,
    })),
    problemTileDelays: tiles.map(t => getComputedStyle(t).transitionDelay),
    enablesParentVisible: document.querySelector('#enables .gb-reveal').classList.contains('visible'),
  };
}

